              "path": "src/client/components/IncidentForm.css",
              "content": ".form-overlay {\n    position: fixed;\n    top: 0;\n    left: 0;\n    right: 0;\n    bottom: 0;\n    background-color: rgba(0, 0, 0, 0.5);\n    display: flex;\n    justify-content: center;\n    align-items: center;\n    z-index: 1000;\n}\n\n.form-container {\n    background-color: white;\n    width: 100%;\n    max-width: 600px;\n    border-radius: 8px;\n    box-shadow: 0 4px 20px rgba(0, 0, 0, 0.15);\n    overflow: hidden;\n}\n\n.form-header {\n    padding: 15px 20px;\n    background-color: #f5f5f5;\n    display: flex;\n    justify-content: space-between;\n    align-items: center;\n    border-bottom: 1px solid #ddd;\n}\n\n.form-header h2 {\n    margin: 0;\n    font-size: 18px;\n    color: #333;\n}\n\n.close-button {\n    background: none;\n    border: none;\n    font-size: 24px;\n    cursor: pointer;\n    color: #666;\n}\n\n.close-button:hover {\n    color: #000;\n}\n\nform {\n    padding: 20px;\n}\n\n.form-group {\n    margin-bottom: 20px;\n}\n\n.form-row {\n    display: flex;\n    gap: 15px;\n}\n\n.form-row .form-group {\n    flex: 1;\n}\n\nlabel {\n    display: block;\n    margin-bottom: 8px;\n    font-weight: 500;\n    color: #333;\n}\n\ninput,\nselect,\ntextarea {\n    width: 100%;\n    padding: 10px;\n    border: 1px solid #ddd;\n    border-radius: 4px;\n    font-size: 14px;\n}\n\ninput:focus,\nselect:focus,\ntextarea:focus {\n    outline: none;\n    border-color: #2196f3;\n    box-shadow: 0 0 0 2px rgba(33, 150, 243, 0.2);\n}\n\n.form-actions {\n    display: flex;\n    justify-content: flex-end;\n    margin-top: 30px;\n    gap: 10px;\n}\n\n.cancel-button,\n.submit-button {\n    padding: 10px 20px;\n    border: none;\n    border-radius: 4px;\n    cursor: pointer;\n    font-weight: 500;\n}\n\n.cancel-button {\n    background-color: #e0e0e0;\n    color: #333;\n}\n\n.cancel-button:hover {\n    background-color: #d5d5d5;\n}\n\n.submit-button {\n    background-color: #4caf50;\n    color: white;\n}\n\n.submit-button:hover {\n    background-color: #45a049;\n}\n"
