              "path": "src/client/components/IncidentForm.vue",
              "content": `<template>
    <div class="form-overlay">
        <div class="form-container">
            <div class="form-header">
                <h2>\\{{ isEditing ? 'Edit Incident' : 'Create New Incident' }}</h2>
                <button type="button" class="close-button" @click="onCancel">\xD7</button>
            </div>
            <form @submit.prevent="handleSubmit">
                <div class="form-group">
                    <label for="short_description">Short Description *</label>
                    <input
                        type="text"
                        id="short_description"
                        name="short_description"
                        v-model="formData.short_description"
                        required
                        maxlength="160"
                    />
                </div>

                <div class="form-group">
                    <label for="description">Description</label>
                    <textarea
                        id="description"
                        name="description"
                        v-model="formData.description"
                        rows="5"
                        maxlength="4000"
                    />
                </div>

                <div class="form-row">
                    <div class="form-group">
                        <label for="state">State</label>
                        <select id="state" name="state" v-model="formData.state">
                            <option value="1">New</option>
                            <option value="2">In Progress</option>
                            <option value="3">On Hold</option>
                            <option value="6">Resolved</option>
                            <option value="7">Closed</option>
                        </select>
                    </div>

                    <div class="form-group">
                        <label for="impact">Impact</label>
                        <select id="impact" name="impact" v-model="formData.impact">
                            <option value="1">1 - High</option>
                            <option value="2">2 - Medium</option>
                            <option value="3">3 - Low</option>
                        </select>
                    </div>
                </div>

                <div class="form-actions">
                    <button type="button" class="cancel-button" @click="onCancel">Cancel</button>
                    <button type="submit" class="submit-button">
                        \\{{ isEditing ? 'Update' : 'Create' }}
                    </button>
                </div>
            </form>
        </div>
    </div>
</template>

<script setup lang="ts">
import { reactive, watch, computed } from 'vue'
import './IncidentForm.css'
import type { Incident } from '../types'

type FormData = {
    short_description: string
    description: string
    state: string
    impact: string
}

const props = defineProps<{
    incident: Incident | null
    onSubmit: (data: FormData) => void
    onCancel: () => void
}>()

const isEditing = computed(() => !!props.incident)

const formData = reactive<FormData>({
    short_description: '',
    description: '',
    state: '1',
    impact: '2',
})

watch(
    () => props.incident,
    (incident) => {
        if (incident) {
            formData.short_description =
                typeof incident.short_description === 'object'
                    ? incident.short_description.value
                    : incident.short_description || ''
            formData.description =
                typeof incident.description === 'object' ? incident.description.value : incident.description || ''
            formData.state = typeof incident.state === 'object' ? incident.state.value : incident.state || 'new'
            formData.impact = typeof incident.impact === 'object' ? incident.impact.value : incident.impact || '3'
        } else {
            formData.short_description = ''
            formData.description = ''
            formData.state = '1'
            formData.impact = '2'
        }
    },
    { immediate: true }
)

const handleSubmit = () => {
    props.onSubmit({ ...formData })
}
<\/script>
`
